# El origen de los trazos (longitud mínima y latitud máxima de la provincia) y unidades por grado.
ORIGEN = (-78.54945989799995, 1.197524058000056)
ESCALA = 589.5286946430584
_POLIGONOS = {nombre: [[tuple(map(float, par.split(','))) for par in anillo.split('L')]
                       for anillo in re.findall(r'M([^MZ]+)Z', trazo)]
              for nombre, trazo in TRAZOS.items()}


def _dentro(x, y, anillo):
    """Regla del rayo: un punto está dentro si cruza los bordes del polígono un número impar de veces."""
    dentro = False
    for (xa, ya), (xb, yb) in zip(anillo, anillo[1:] + anillo[:1]):
        if (ya > y) != (yb > y) and x < (xb - xa) * (y - ya) / (yb - ya) + xa:
            dentro = not dentro
    return dentro


def canton_de(latitud, longitud):
    """El cantón del Carchi donde cae un punto, o None si está fuera de la provincia."""
    x, y = (longitud - ORIGEN[0]) * ESCALA, (ORIGEN[1] - latitud) * ESCALA
    for nombre, anillos in _POLIGONOS.items():
        if any(_dentro(x, y, anillo) for anillo in anillos):
            return nombre
    return None
